    """Existing documents default to 'uploader'. Mark the ones a Drive import
    created from its results: a checklist slot it filled by filename ->
    'filename'; an additional file (stored as 'supporting_document') -> 'none'.
    document_type itself is left as it was -- the original label."""
    Document = apps.get_model('documents', 'Document')
    DriveImportJob = apps.get_model('documents', 'DriveImportJob')

    by_filename, unmatched = set(), set()
    for results in DriveImportJob.objects.values_list('results', flat=True):
        if not isinstance(results, dict):
            continue
        for key, value in results.items():
            if key == 'additional_files' and isinstance(value, list):
                unmatched.update(f.get('document_id') for f in value if isinstance(f, dict))
            elif isinstance(value, dict) and value.get('status') == 'found':
                by_filename.add(value.get('document_id'))

    Document.objects.filter(id__in=[i for i in by_filename if i]).update(document_type_source='filename')
    Document.objects.filter(id__in=[i for i in unmatched if i]).update(document_type_source='none')


